 for(const id of [gmail,icloud,stranger]){await db.query('insert into auth.users values($1)',[id]);await db.query('insert into coaching_remote_users values($1,$2,true,true)',[id,id===gmail?'Sébastien':id===icloud?'seb.lobstein':'Autre']);}
 await db.exec('update private.community_friendship_control set enabled=true');
 async function friendship(actor,peer,action,version,enabled=null){return db.query('select community_friendship_command($1,$2,$3,$4,$5,$6)',[actor,peer,action,crypto.randomUUID(),version,enabled]);}
 await friendship(gmail,icloud,'contact-request',-1);await friendship(icloud,gmail,'accept-contact',0);await friendship(gmail,icloud,'set-contact-permission',1,true);await friendship(icloud,gmail,'set-contact-permission',2,true);
 const admin={from(table){assert.match(table,/^coaching_remote_(users|sessions|invites|commands)$/);let fields='*',where=[],args=[],action='select',values,one=false,sort='',limit='';const bind=v=>{args.push(v);return '$'+args.length;};const q={select(s='*'){fields=s;return q;},eq(k,v){where.push(`${k}=${bind(v)}`);return q;},is(k,v){assert.equal(v,null);where.push(`${k} is null`);return q;},gt(k,v){where.push(`${k}>${bind(v)}`);return q;},contains(k,v){where.push(`${k} @> ${bind(JSON.stringify(v))}::jsonb`);return q;},order(k,{ascending=true}={}){sort=` order by ${k} ${ascending?'asc':'desc'}`;return q;},limit(n){limit=' limit '+Number(n);return q;},maybeSingle(){one=true;return q;},insert(v){action='insert';values=v;return q;},upsert(v){action='upsert';values=v;return q;},update(v){action='update';values=v;return q;},async then(resolve,reject){try{let sql;if(action==='select')sql=`select ${fields} from ${table}`;else if(action==='update')sql=`update ${table} set `+Object.entries(values).map(([k,v])=>`${k}=${bind(v)}`).join(',');else sql=`insert into ${table} (${Object.keys(values)}) values (${Object.values(values).map(bind)})`+(action==='upsert'?' on conflict do nothing':'');if(where.length)sql+=' where '+where.join(' and ');sql+=sort+limit;if(action!=='select')sql+=' returning *';const r=await db.query(sql,args);resolve({data:one?r.rows[0]||null:r.rows});}catch(e){resolve({error:{code:e.code,message:e.message}});}}};return q;},async rpc(name,p){assert.equal(name,'coaching_commit');try{return {data:(await db.query('select coaching_commit($1,$2,$3,$4,$5,$6,$7,$8) result',[p.p_session_id,p.p_actor_id,p.p_command_id,p.p_fingerprint,p.p_expected,p.p_state,p.p_invite,p.p_batch])).rows[0].result};}catch(e){return {error:{code:e.code,message:e.message}};}}};
 const handler=createCoachingHandler({admin,coachingInboxEnabled:true,authClient:{auth:{getUser:async id=>({data:{user:{id}}})}},teamContactsProvider:async id=>(await db.query('select community_coaching_contacts($1) contacts',[id])).rows[0].contacts});
